# Code Generated by Sidekick is for learning and experimentation purposes only.
# filename: app/observability/slo_metrics.py
from prometheus_client import Counter, Gauge, Histogram

BOOKING_API_RESULTS_TOTAL = Counter(
    "booking_api_results_total",
    "Booking API outcomes included in SLO calculations",
    ["outcome"],
)

HOLD_API_RESULTS_TOTAL = Counter(
    "hold_api_results_total",
    "Hold API outcomes included in SLO calculations",
    ["outcome"],
)

BOOKING_API_LATENCY_SECONDS = Histogram(
    "booking_api_latency_seconds",
    "End-to-end latency for POST /bookings",
    buckets=(0.1, 0.2, 0.3, 0.5, 0.75, 1.0, 1.5, 2.0, 3.0, 5.0, 10.0),
)

PAYMENT_COMPLETION_LATENCY_SECONDS = Histogram(
    "payment_completion_latency_seconds",
    "Time from payment processing start to final completion state",
    ["outcome"],
    buckets=(0.1, 0.2, 0.3, 0.5, 0.75, 1.0, 1.5, 2.0, 3.0, 5.0, 10.0),
)

DEPENDENCY_PROBE_TOTAL = Counter(
    "dependency_probe_total",
    "Dependency probe results",
    ["dependency", "outcome"],
)

DEPENDENCY_UP = Gauge(
    "dependency_up",
    "Latest dependency probe status",
    ["dependency"],
)


def record_booking_api_result(outcome: str) -> None:
    BOOKING_API_RESULTS_TOTAL.labels(outcome=outcome).inc()


def record_hold_api_result(outcome: str) -> None:
    HOLD_API_RESULTS_TOTAL.labels(outcome=outcome).inc()


def observe_booking_api_latency(seconds: float) -> None:
    BOOKING_API_LATENCY_SECONDS.observe(seconds)


def observe_payment_completion_latency(seconds: float, outcome: str) -> None:
    PAYMENT_COMPLETION_LATENCY_SECONDS.labels(outcome=outcome).observe(seconds)


def record_dependency_probe(dependency: str, ok: bool) -> None:
    DEPENDENCY_UP.labels(dependency=dependency).set(1 if ok else 0)
    DEPENDENCY_PROBE_TOTAL.labels(
        dependency=dependency,
        outcome="success" if ok else "failure",
    ).inc()
